class newobject(object):

    def next(self):
        if hasattr(self, b'__next__'):
            return type(self).__next__(self)
        raise TypeError(b'newobject is not an iterator')
        return

    def __unicode__(self):
        if hasattr(self, b'__str__'):
            s = type(self).__str__(self)
        else:
            s = str(self)
        if isinstance(s, unicode):
            return s
        else:
            return s.decode(b'utf-8')

        return

    def __nonzero__(self):
        if hasattr(self, b'__bool__'):
            return type(self).__bool__(self)
        if hasattr(self, b'__len__'):
            return type(self).__len__(self)
        return True

    def __long__(self):
        if not hasattr(self, b'__int__'):
            return NotImplemented
        return self.__int__()

    def __native__(self):
        return object(self)

    __slots__ = []


__all__ = [
 b'newobject']
